import{_ as l,a0 as d,w as h,s as o,ao as n,I as p,x as e,a1 as i,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"通过实例学习 tcpdump 命令 | LCTT x X-CMD","titleTemplate":false,"description":"通过实例学习 tcpdump 命令 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"通过实例学习 tcpdump 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"通过实例学习 tcpdump 命令 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171109 Learn how to use tcpdump command with examples","title":"通过实例学习 tcpdump 命令","tag":"201801","desc":""},"relativePath":"201801/20171109 Learn how to use tcpdump command with examples.md","filePath":"[post].md"}'),r={name:"201801/20171109 Learn how to use tcpdump command with examples.md"};function c(u,a,g,k,b,m){const s=d("Link");return h(),o("div",null,[a[15]||(a[15]=n('<h1 id="通过实例学习-tcpdump-命令" tabindex="-1">通过实例学习 tcpdump 命令 <a class="header-anchor" href="#通过实例学习-tcpdump-命令" aria-label="Permalink to “通过实例学习 tcpdump 命令”">​</a></h1><p><code>tcpdump</code> 是一个很常用的网络包分析工具，可以用来显示通过网络传输到本系统的 TCP/IP 以及其他网络的数据包。<code>tcpdump</code> 使用 libpcap 库来抓取网络报，这个库在几乎在所有的 Linux/Unix 中都有。</p><p><code>tcpdump</code> 可以从网卡或之前创建的数据包文件中读取内容，也可以将包写入文件中以供后续使用。必须是 root 用户或者使用 sudo 特权来运行 <code>tcpdump</code>。</p><p>在本文中，我们将会通过一些实例来演示如何使用 <code>tcpdump</code> 命令，但首先让我们来看看在各种 Linux 操作系统中是如何安装 <code>tcpdump</code> 的。</p>',4)),p("ul",null,[p("li",null,[a[1]||(a[1]=e("推荐阅读：",-1)),i(s,{href:"http://linuxtechlab.com/monitoring-network-bandwidth-iftop-command/"},{default:t(()=>[...a[0]||(a[0]=[e("使用 iftop 命令监控网络带宽 ",-1)])]),_:1})])]),a[16]||(a[16]=n(`<h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h3><p><code>tcpdump</code> 默认在几乎所有的 Linux 发行版中都可用，但若你的 Linux 上没有的话，使用下面方法进行安装。</p><h4 id="centos-rhel" tabindex="-1">CentOS/RHEL <a class="header-anchor" href="#centos-rhel" aria-label="Permalink to “CentOS/RHEL”">​</a></h4><p>使用下面命令在 CentOS 和 RHEL 上安装 <code>tcpdump</code>，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install tcpdump*</span></span></code></pre></div><h4 id="fedora" tabindex="-1">Fedora <a class="header-anchor" href="#fedora" aria-label="Permalink to “Fedora”">​</a></h4><p>使用下面命令在 Fedora 上安装 <code>tcpdump</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dnf install tcpdump</span></span></code></pre></div><h4 id="ubuntu-debian-linux-mint" tabindex="-1">Ubuntu/Debian/Linux Mint <a class="header-anchor" href="#ubuntu-debian-linux-mint" aria-label="Permalink to “Ubuntu/Debian/Linux Mint”">​</a></h4><p>在 Ubuntu/Debain/Linux Mint 上使用下面命令安装 <code>tcpdump</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ apt-get install tcpdump</span></span></code></pre></div><p>安装好 <code>tcpdump</code> 后，现在来看一些例子。</p><h3 id="案例演示" tabindex="-1">案例演示 <a class="header-anchor" href="#案例演示" aria-label="Permalink to “案例演示”">​</a></h3><h4 id="从所有网卡中捕获数据包" tabindex="-1">从所有网卡中捕获数据包 <a class="header-anchor" href="#从所有网卡中捕获数据包" aria-label="Permalink to “从所有网卡中捕获数据包”">​</a></h4><p>运行下面命令来从所有网卡中捕获数据包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tcpdump -i any</span></span></code></pre></div><h4 id="从指定网卡中捕获数据包" tabindex="-1">从指定网卡中捕获数据包 <a class="header-anchor" href="#从指定网卡中捕获数据包" aria-label="Permalink to “从指定网卡中捕获数据包”">​</a></h4><p>要从指定网卡中捕获数据包，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tcpdump -i eth0</span></span></code></pre></div><h4 id="将捕获的包写入文件" tabindex="-1">将捕获的包写入文件 <a class="header-anchor" href="#将捕获的包写入文件" aria-label="Permalink to “将捕获的包写入文件”">​</a></h4><p>使用 <code>-w</code> 选项将所有捕获的包写入文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tcpdump -i eth1 -w packets_file</span></span></code></pre></div><h4 id="读取之前产生的-tcpdump-文件" tabindex="-1">读取之前产生的 tcpdump 文件 <a class="header-anchor" href="#读取之前产生的-tcpdump-文件" aria-label="Permalink to “读取之前产生的 tcpdump 文件”">​</a></h4><p>使用下面命令从之前创建的 tcpdump 文件中读取内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tcpdump -r packets_file</span></span></code></pre></div><h4 id="获取更多的包信息-并且以可读的形式显示时间戳" tabindex="-1">获取更多的包信息，并且以可读的形式显示时间戳 <a class="header-anchor" href="#获取更多的包信息-并且以可读的形式显示时间戳" aria-label="Permalink to “获取更多的包信息，并且以可读的形式显示时间戳”">​</a></h4><p>要获取更多的包信息同时以可读的形式显示时间戳，使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tcpdump -ttttnnvvS</span></span></code></pre></div><h4 id="查看整个网络的数据包" tabindex="-1">查看整个网络的数据包 <a class="header-anchor" href="#查看整个网络的数据包" aria-label="Permalink to “查看整个网络的数据包”">​</a></h4><p>要获取整个网络的数据包，在终端执行下面命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tcpdump net 192.168.1.0/24</span></span></code></pre></div><h4 id="根据-ip-地址查看报文" tabindex="-1">根据 IP 地址查看报文 <a class="header-anchor" href="#根据-ip-地址查看报文" aria-label="Permalink to “根据 IP 地址查看报文”">​</a></h4><p>要获取指定 IP 的数据包，不管是作为源地址还是目的地址，使用下面命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tcpdump host 192.168.1.100</span></span></code></pre></div><p>要指定 IP 地址是源地址或是目的地址则使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tcpdump src 192.168.1.100</span></span>
<span class="line"><span>$ tcpdump dst 192.168.1.100</span></span></code></pre></div><h4 id="查看某个协议或端口号的数据包" tabindex="-1">查看某个协议或端口号的数据包 <a class="header-anchor" href="#查看某个协议或端口号的数据包" aria-label="Permalink to “查看某个协议或端口号的数据包”">​</a></h4><p>要查看某个协议的数据包，运行下面命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tcpdump ssh</span></span></code></pre></div><p>要捕获某个端口或一个范围的数据包，使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tcpdump port 22</span></span>
<span class="line"><span>$ tcpdump portrange 22-125</span></span></code></pre></div><p>我们也可以与 <code>src</code> 和 <code>dst</code> 选项连用来捕获指定源端口或指定目的端口的报文。</p><p>我们还可以使用“与” （<code>and</code>，<code>&amp;&amp;</code>）、“或” （<code>or</code>，<code>||</code> ) 和“非”（<code>not</code>，<code>!</code>） 来将两个条件组合起来。当我们需要基于某些条件来分析网络报文是非常有用。</p><h4 id="使用-与" tabindex="-1">使用“与” <a class="header-anchor" href="#使用-与" aria-label="Permalink to “使用“与””">​</a></h4><p>可以使用 <code>and</code> 或者符号 <code>&amp;&amp;</code> 来将两个或多个条件组合起来。比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tcpdump src 192.168.1.100 &amp;&amp; port 22 -w ssh_packets</span></span></code></pre></div><h4 id="使用-或" tabindex="-1">使用“或” <a class="header-anchor" href="#使用-或" aria-label="Permalink to “使用“或””">​</a></h4><p>“或”会检查是否匹配命令所列条件中的其中一条，像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tcpdump src 192.168.1.100 or dst 192.168.1.50 &amp;&amp; port 22 -w ssh_packets</span></span>
<span class="line"><span>$ tcpdump port 443 or 80 -w http_packets</span></span></code></pre></div><h4 id="使用-非" tabindex="-1">使用“非” <a class="header-anchor" href="#使用-非" aria-label="Permalink to “使用“非””">​</a></h4><p>当我们想表达不匹配某项条件时可以使用“非”，像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tcpdump -i eth0 src port not 22</span></span></code></pre></div><p>这会捕获 eth0 上除了 22 号端口的所有通讯。</p><p>我们的教程至此就结束了，在本教程中我们讲解了如何安装并使用 <code>tcpdump</code> 来捕获网络数据包。如有任何疑问或建议，欢迎留言。</p><hr>`,55)),p("p",null,[a[3]||(a[3]=e("via: ",-1)),i(s,{href:"http://linuxtechlab.com/learn-use-tcpdump-command-examples/"},{default:t(()=>[...a[2]||(a[2]=[e("http://linuxtechlab.com/learn-use-tcpdump-command-examples/",-1)])]),_:1})]),p("p",null,[a[7]||(a[7]=e("作者：",-1)),i(s,{href:"http://linuxtechlab.com/author/shsuain/"},{default:t(()=>[...a[4]||(a[4]=[e("Shusain",-1)])]),_:1}),a[8]||(a[8]=e(" 译者：",-1)),i(s,{href:"https://github.com/lujun9972"},{default:t(()=>[...a[5]||(a[5]=[e("lujun9972",-1)])]),_:1}),a[9]||(a[9]=e(" 校对：",-1)),i(s,{href:"https://github.com/wxy"},{default:t(()=>[...a[6]||(a[6]=[e("wxy",-1)])]),_:1})]),p("p",null,[a[12]||(a[12]=e("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...a[10]||(a[10]=[e("LCTT",-1)])]),_:1}),a[13]||(a[13]=e(" 原创编译，",-1)),i(s,{href:"https://linux.cn/"},{default:t(()=>[...a[11]||(a[11]=[e("Linux中国",-1)])]),_:1}),a[14]||(a[14]=e(" 荣誉推出",-1))])])}const y=l(r,[["render",c]]);export{C as __pageData,y as default};
